-- Resources: Sourcework tutorial guides (docs/resources-design.md slice 5).
-- Three gaps in the tool's guide set: starting a project, working the
-- transcript/excerpts, and search -- alongside the two guides seeded with
-- Resources itself (reference-another-source, browse-source-library).
-- Content only. Upserts on slug; guarded by edited_since_release.

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'sourcework-starting-a-project', 'guide'::public.rc_kind, 'Starting a project and uploading a source', 'Upload a recording or PDF and Sourcework starts processing it right away.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project starts with one file — a recording, or a PDF document."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a project"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Sourcework home page, select "},{"type":"text","text":"New project","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a file: audio (WAV, MP3, M4A/AAC), video (MP4, MOV, WebM), or a PDF."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The title fills in from the file name — change it to whatever you''ll look for later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add optional notes for context, then select "},{"type":"text","text":"Upload and create project","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"While it processes"}]},{"type":"paragraph","content":[{"type":"text","text":"The button shows its own progress — "},{"type":"text","text":"Uploading…","marks":[{"type":"italic"}]},{"type":"text","text":", then "},{"type":"text","text":"Finishing up…","marks":[{"type":"italic"}]},{"type":"text","text":" — before it takes you to the new project. Processing continues from there in the background: a banner explains what''s still running, and the page updates on its own once it''s done."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio and video get a transcript."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF''s text is extracted automatically — a plain read of the file first, falling back to OCR only when that isn''t enough."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If processing fails, the project page offers "},{"type":"text","text":"Retry transcription","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Retry text extraction","marks":[{"type":"bold"}]},{"type":"text","text":". Either way, the file itself is already safely uploaded."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything outside the accepted audio, video, and PDF types is rejected before the upload starts, with a message naming what is accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The file goes straight from your browser to storage. A long recording can take a few minutes to upload — most of that time is the upload itself, not processing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a source is uploaded, it can be used in more than one project with no re-upload — see "},{"type":"text","text":"Reference another source in a project","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{sourcework.projects}'::text[], 5, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'transcription'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'sourcework-transcript-and-excerpts', 'guide'::public.rc_kind, 'Working with the transcript and creating excerpts', 'Select a stretch of the transcript to save it as a clip you can trim, preview, and export.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every project''s transcript is on the left. Excerpts — short clips saved for reuse — are pulled from it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create an excerpt"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag to select the stretch of text you want, in the transcript."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"New excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" panel opens, showing the time range and the quoted text."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give it a title, then select "},{"type":"text","text":"Create excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" — or "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" first to listen to the exact range."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Excerpts panel lists every one you''ve made, with the count in its heading."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nudge the start or end of a clip with the trim buttons — a small step or a larger one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export WAV","marks":[{"type":"bold"}]},{"type":"text","text":" renders the clip to its own audio file; "},{"type":"text","text":"Download","marks":[{"type":"bold"}]},{"type":"text","text":" appears once that''s ready. "},{"type":"text","text":"Export all (zip)","marks":[{"type":"bold"}]},{"type":"text","text":" does every excerpt in the project at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a card''s title to rename it. "},{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" asks you to confirm before it removes one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range — its excerpts appear in the same panel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trimming a clip after it''s been exported makes that export stale. Re-export before you rely on the download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A search box above the panel searches this source''s transcript and its excerpts together."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{sourcework.project,sourcework.source}'::text[], 15, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'transcription'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'sourcework-search', 'guide'::public.rc_kind, 'Searching across projects and sources', 'Find a transcript, excerpt, or interview by what was said — and what it was about, once topic search is configured.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The search box on the Sourcework home page searches every project, source, transcript, and excerpt you have access to — enter a term and go."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How results work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Results are ranked by relevance and labeled by kind — project, transcript, document, or excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Clear search","marks":[{"type":"bold"}]},{"type":"text","text":" to return to the ordinary project list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The same kind of search box appears again inside a project workspace and inside the Excerpts panel, narrowed to just that source."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The hint line under the search box says what kind of search is active: “Searches what was said and what it was about” once topic search is configured for this portal, or “Searches the words that were said” — an exact match only — when it isn''t."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Topic search (finding a passage by what it''s about, not just its exact wording) depends on an optional service being configured. If it''s off, keyword search still finds everything — it just won''t catch a paraphrase."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing errors when topic search is off. The hint line under the box is the only place this is shown."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{sourcework.projects,sourcework.project,sourcework.source}'::text[], 25, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'transcription'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

